import { generateId } from '@hse/shared';
import { integer, text } from 'drizzle-orm/sqlite-core';

/**
 * Reusable column sets required by the Database Rules and Product Book Doc 04.
 * Spread them into every table definition:
 *
 * @example
 * export const inspection = sqliteTable('inspection', {
 *   ...primaryKey(),
 *   ...auditColumns(),
 *   ...softDeleteColumns(),
 *   title: text('title').notNull(),
 * });
 *
 * Physical types for D1 / SQLite (see 03_DATABASE.md): UUID as TEXT, timestamps as
 * INTEGER epoch milliseconds in UTC.
 */

/** UUID primary key generated by the application; it never carries business meaning. */
export const primaryKey = () => ({
  id: text('id')
    .primaryKey()
    .$defaultFn(() => generateId()),
});

const utcTimestamp = (name: string) => integer(name, { mode: 'timestamp_ms' });

/**
 * created_at / created_by / updated_at / updated_by.
 * `*_by` holds a user id; it is null only for system-generated changes.
 * The user foreign key is added once the identity module defines the `user` table (Sprint 1).
 */
export const auditColumns = () => ({
  createdAt: utcTimestamp('created_at')
    .notNull()
    .$defaultFn(() => new Date()),
  createdBy: text('created_by'),
  updatedAt: utcTimestamp('updated_at')
    .notNull()
    .$defaultFn(() => new Date())
    .$onUpdateFn(() => new Date()),
  updatedBy: text('updated_by'),
});

/** deleted_at / deleted_by for tables whose records are archived, never removed. */
export const softDeleteColumns = () => ({
  deletedAt: utcTimestamp('deleted_at'),
  deletedBy: text('deleted_by'),
});
